package com.ecommerce.cart; import com.ecommerce.product.Product; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="cart_items",uniqueConstraints=@UniqueConstraint(columnNames={"cart_id","product_id"})) public class CartItem { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="cart_id",nullable=false) Cart cart; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="product_id",nullable=false) Product product; @Column(nullable=false) int quantity; public UUID getId(){return id;} public Product getProduct(){return product;} public int getQuantity(){return quantity;} public void setCart(Cart v){cart=v;} public void setProduct(Product v){product=v;} public void setQuantity(int v){quantity=v;} }
